{
  "modes": [
    {
      "label": "1 GbE 1000BASE-LX",
      "media_interface_name": "1000BASE-LX",
      "standards_code": "1000BASE-LX",
      "bit_rate_gbps": 1.0
    },
    {
      "label": "4G FC 400-M5E-SN-I",
      "media_interface_name": "400-M5E-SN-I",
      "standards_code": "400-M5E-SN-I",
      "bit_rate_gbps": 4.0
    },
    {
      "label": "8G FC 800-M5E-SN-I",
      "media_interface_name": "800-M5E-SN-I",
      "standards_code": "800-M5E-SN-I",
      "bit_rate_gbps": 8.5
    }
  ]
}
```
